function noise(x,y){const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)}
function smooth(x,y){const ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy,sx=fx*fx*(3-2*fx),sy=fy*fy*(3-2*fy);return T.MathUtils.lerp(T.MathUtils.lerp(noise(ix,iy),noise(ix+1,iy),sx),T.MathUtils.lerp(noise(ix,iy+1),noise(ix+1,iy+1),sx),sy)}
function fbm(x,y){let v=0,a=.5;for(let i=0;i<5;i++){v+=a*smooth(x,y);x=x*2.02+7;y=y*2.03+3;a*=.5}return v}
function planetTexture(index){const c=document.createElement('canvas');c.width=1024;c.height=512;const cx=c.getContext('2d'),im=cx.createImageData(1024,512),base=new T.Color(planets[index][2]);for(let y=0;y<512;y++)for(let x=0;x<1024;x++){const u=x/1024,v=y/512,n=fbm(u*12,v*9),d=(y*1024+x)*4;let r=base.r*255,g=base.g*255,b=base.b*255;if(index===2){const land=fbm(u*8+Math.sin(v*8)*.5,v*6);if(land>.51){const h=(land-.51)*3;r=35+h*140;g=83+h*100;b=48+h*50}else{r=12+n*14;g=46+n*65;b=100+n*95}if(Math.abs(v-.5)>.43+noise(x*.04,y*.02)*.025){r=190;g=215;b=225}const cloud=fbm(u*24+Math.sin(v*17),v*19);if(cloud>.62){const a=(cloud-.62)*6;r=r*(1-a)+235*a;g=g*(1-a)+242*a;b=b*(1-a)+255*a}}
else if(index===4||index===5){const f=.6+n*.7+Math.sin(v*100+fbm(u*8,v*12)*5)*.13+Math.sin(v*270)*.025;r*=f;g*=f;b*=f;if(index===4&&((u-.65)**2/.012+(v-.61)**2/.002)<1){r=174+n*35;g=80+n*40;b=54+n*25}}
else{const f=.55+n*.85;r*=f;g*=f;b*=f;if(index===0&&smooth(u*70,v*35)<.25){r*=.65;g*=.65;b*=.65}}im.data[d]=Math.min(255,r);im.data[d+1]=Math.min(255,g);im.data[d+2]=Math.min(255,b);im.data[d+3]=255}cx.putImageData(im,0,0);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;return tex}
function selectPlanet(n){selected=n;const p=planets[n];$('#planet-title').innerHTML=p[0]+' <span>'+p[1]+'</span>';$('#planet-desc').textContent=p[0]+' 궤도 방어 · 외계 함대를 격퇴하라.';$('#sector').textContent='SECTOR '+String(n+1).padStart(2,'0')+' / 08';document.querySelectorAll('#planet-picker button').forEach((b,i)=>b.classList.toggle('active',i===n));if(planetGroup){scene.remove(planetGroup);planetGroup.traverse(o=>{o.geometry?.dispose();if(o.material){if(o.material.map&&![...textures.values()].includes(o.material.map))o.material.map.dispose();o.material.dispose()}})}planetGroup=new T.Group();planetGroup.position.set(65,28,-170);scene.add(planetGroup);if(!textures.has(n))textures.set(n,planetTexture(n));const body=mesh(new T.SphereGeometry(57,96,64),new T.MeshStandardMaterial({map:textures.get(n),roughness:.9,metalness:.02}),planetGroup);body.rotation.z=.18;body.rotation.y=-.6;planetGroup.userData.body=body;
mesh(new T.SphereGeometry(58.5,64,48),new T.ShaderMaterial({uniforms:{color:{value:new T.Color(n===3?0xff8957:n===5?0xecd8a2:0x71c8ff)}},vertexShader:'varying vec3 vN;varying vec3 vP;void main(){vec4 p=modelViewMatrix*vec4(position,1.);vN=normalize(normalMatrix*normal);vP=-p.xyz;gl_Position=projectionMatrix*p;}',fragmentShader:'uniform vec3 color;varying vec3 vN;varying vec3 vP;void main(){float f=pow(1.-max(dot(normalize(vN),normalize(vP)),0.),3.5);gl_FragColor=vec4(color,f*.65);}',transparent:true,blending:T.AdditiveBlending,depthWrite:false}),planetGroup);
if(n===5){const c=document.createElement('canvas');c.width=512;c.height=8;const x=c.getContext('2d');for(let i=0;i<512;i++){x.fillStyle=`rgba(215,192,145,${(.18+Math.random()*.6)*(i>260&&i<280?.12:1)})`;x.fillRect(i,0,1,8)}const tex=new T.CanvasTexture(c),geo=new T.RingGeometry(68,104,128),pos=geo.attributes.position,uv=geo.attributes.uv;for(let i=0;i<pos.count;i++)uv.setXY(i,(Math.hypot(pos.getX(i),pos.getY(i))-68)/36,.5);mesh(geo,new T.MeshBasicMaterial({map:tex,transparent:true,opacity:.8,side:T.DoubleSide,depthWrite:false}),planetGroup).rotation.set(1.12,.2,-.35)}if(!textures.has(0))textures.set(0,planetTexture(0));mesh(new T.SphereGeometry(8,32,24),new T.MeshStandardMaterial({map:textures.get(0),color:0x9da3b6,roughness:1}),planetGroup,-92,-10,-30);}
function init(){renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,mobile?1.4:1.8));renderer.setSize(W,H);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;$('#universe').appendChild(renderer.domElement);scene=new T.Scene();scene.background=new T.Color(0x02040d);camera=new T.PerspectiveCamera(62,W/H,.1,1500);camera.position.set(0,4,18);scene.add(new T.HemisphereLight(0xa9cfff,0x17122a,2.3));const sun=new T.DirectionalLight(0xffedcf,4.5);sun.position.set(-100,60,60);scene.add(sun);const rim=new T.DirectionalLight(0x528eff,2);rim.position.set(80,-10,-50);scene.add(rim);
const c=document.createElement('canvas');c.width=c.height=128;const cx=c.getContext('2d'),gr=cx.createRadialGradient(64,64,0,64,64,64);gr.addColorStop(0,'#fff');gr.addColorStop(.12,'#fff');gr.addColorStop(.3,'#ffffff60');gr.addColorStop(1,'#ffffff00');cx.fillStyle=gr;cx.fillRect(0,0,128,128);glowTexture=new T.CanvasTexture(c);const geo=new T.BufferGeometry(),sp=[],sc=[];for(let i=0;i<4200;i++){const v=new V(Math.random()-.5,Math.random()-.5,Math.random()-.5).normalize().multiplyScalar(400+Math.random()*650);sp.push(v.x,v.y,v.z);const col=new T.Color().setHSL(.54+Math.random()*.15,.2+Math.random()*.3,.45+Math.random()*.5);sc.push(col.r,col.g,col.b)}geo.setAttribute('position',new T.Float32BufferAttribute(sp,3));geo.setAttribute('color',new T.Float32BufferAttribute(sc,3));stars=new T.Points(geo,new T.PointsMaterial({size:1.2,map:glowTexture,vertexColors:true,transparent:true,depthWrite:false,blending:T.AdditiveBlending}));scene.add(stars);for(let i=0;i<22;i++){const neb=glow(i%3===0?0x6539ad:i%3===1?0x124b7c:0x215267,240+Math.random()*230,scene,(Math.random()-.5)*850,(Math.random()-.5)*380,-450-Math.random()*200);neb.material.opacity=.065}glow(0xffc287,80,scene,-160,55,-240);glow(0xffead0,18,scene,-160,55,-239);
world=new T.Group();scene.add(world);player=fighter(0,true);world.add(player);for(let i=0;i<12;i++){const g=fighter(i,i<5);g.scale.setScalar(.75+Math.random()*.6);g.position.set((Math.random()-.5)*100,(Math.random()-.5)*35,-35-Math.random()*100);world.add(g);allies.push({mesh:g,speed:12+Math.random()*20,seed:Math.random()*10,friendly:i<5})}for(let i=0;i<3;i++){const g=capital();g.scale.setScalar(i?.75:1.4);g.position.set(i===2?85:i?-55:-80,i?19:0,i?-140:-180);g.rotation.y=i?.35:-.4;scene.add(g)}particleGeo=new T.BufferGeometry();particlePositions=new Float32Array(2200*3);particleColors=new Float32Array(2200*3);particleGeo.setAttribute('position',new T.BufferAttribute(particlePositions,3).setUsage(T.DynamicDrawUsage));particleGeo.setAttribute('color',new T.BufferAttribute(particleColors,3).setUsage(T.DynamicDrawUsage));particleGeo.setDrawRange(0,0);const points=new T.Points(particleGeo,new T.PointsMaterial({size:.65,map:glowTexture,transparent:true,vertexColors:true,blending:T.AdditiveBlending,depthWrite:false}));points.frustumCulled=false;scene.add(points);
planets.forEach((p,i)=>{const b=document.createElement('button');b.title=p[0]+' 전장';b.setAttribute('aria-label',p[0]+' 전장 선택');b.innerHTML=`<i style="background:${p[2]}"></i>`;b.onclick=()=>{if(mode==='intro'){sfx.init();selectPlanet(i);sfx.ui()}};$('#planet-picker').appendChild(b)});selectPlanet(selected);const bar=document.createElement('div');bar.id='weapon-bar';bar.hidden=true;weapons.forEach((w,i)=>{const b=document.createElement('button');b.innerHTML=`<kbd>${i+1}</kbd><span>${w.name}</span><i></i>`;b.onclick=()=>setWeapon(i);b.title=w.name+' ('+(i+1)+')';bar.appendChild(b)});document.body.appendChild(bar);setWeapon(0);$('#loading').hidden=true;requestAnimationFrame(loop)}
function setWeapon(i){weapon=i;document.querySelectorAll('#weapon-bar button').forEach((b,n)=>b.classList.toggle('active',n===i));if(mode==='play'){notify(weapons[i].name,.9);sfx.weapon(i)}}
// 사운드 엔진: 모든 효과음·배경음악을 Web Audio로 실시간 합성. 마스터 볼륨 → 컴프레서 → 출력, 공용 리버브 버스.
const sfx=(()=>{let ctx,master,verbIn,noiseBuf,bgmBus,boostSrc,boostGain,boostFilter,timer,step=0,next=0,level=0,playing=false;const gates={};let volume=.8,muted=false;
try{const v=localStorage.getItem('solarWarVolume');if(v!==null)volume=T.MathUtils.clamp(Number(v),0,1);muted=localStorage.getItem('solarWarMuted')==='1'}catch{}
const live=()=>ctx&&ctx.state==='running'&&!muted&&volume>0,gate=(k,ms)=>{const n=performance.now();if(n-(gates[k]||0)<ms)return false;gates[k]=n;return true},rnd=(a,b)=>a+Math.random()*(b-a);
function applyVolume(){if(master)master.gain.setTargetAtTime(muted?0:volume*volume*1.2,ctx.currentTime,.03);try{localStorage.setItem('solarWarVolume',volume);localStorage.setItem('solarWarMuted',muted?'1':'0')}catch{}const b=$('#sound');if(b){b.textContent=muted||volume===0?'MUTE':'SOUND '+Math.round(volume*100)+'%';b.classList.toggle('muted',muted||volume===0)}const r=$('#volume');if(r)r.value=Math.round(volume*100)}
function init(){if(ctx){if(ctx.state==='suspended'&&!paused)ctx.resume();return}try{ctx=new(window.AudioContext||window.webkitAudioContext)()}catch{return}const comp=ctx.createDynamicsCompressor();comp.threshold.value=-12;comp.knee.value=16;comp.ratio.value=6;comp.attack.value=.002;comp.release.value=.3;master=ctx.createGain();master.gain.value=0;master.connect(comp);comp.connect(ctx.destination);
const len=ctx.sampleRate*3,ir=ctx.createBuffer(2,len,ctx.sampleRate);for(let c=0;c<2;c++){const d=ir.getChannelData(c);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/len,3)}const verb=ctx.createConvolver();verb.buffer=ir;verbIn=ctx.createGain();verbIn.gain.value=.6;verbIn.connect(verb);verb.connect(master);
noiseBuf=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate);const n=noiseBuf.getChannelData(0);for(let i=0;i<n.length;i++)n[i]=Math.random()*2-1;bgmBus=ctx.createGain();bgmBus.gain.value=0;bgmBus.connect(master);const bw=ctx.createGain();bw.gain.value=.25;bgmBus.connect(bw);bw.connect(verbIn);
boostSrc=ctx.createBufferSource();boostSrc.buffer=noiseBuf;boostSrc.loop=true;boostFilter=ctx.createBiquadFilter();boostFilter.type='bandpass';boostFilter.frequency.value=400;boostFilter.Q.value=.9;boostGain=ctx.createGain();boostGain.gain.value=0;boostSrc.connect(boostFilter);boostFilter.connect(boostGain);boostGain.connect(master);boostSrc.start();applyVolume()}
function out(dest,wet,pan){const g=ctx.createGain();let n=g;if(pan&&ctx.createStereoPanner){const p=ctx.createStereoPanner();p.pan.value=T.MathUtils.clamp(pan,-1,1);g.connect(p);n=p}n.connect(dest||master);if(wet){const s=ctx.createGain();s.gain.value=wet;n.connect(s);s.connect(verbIn)}return g}
function env(g,t,vol,attack,dur){g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+attack);g.gain.exponentialRampToValueAtTime(.0001,t+dur)}
function osc(type,f0,f1,dur,vol,{at=0,t=ctx.currentTime+at,wet=0,pan=0,attack=.004,detune=0,lp=0,dest}={}){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.detune.value=detune;o.frequency.setValueAtTime(f0,t);if(f1!==f0)o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+dur);env(g,t,vol,attack,dur);let n=o;if(lp){const f=ctx.createBiquadFilter();f.type='lowpass';f.frequency.setValueAtTime(lp,t);f.frequency.exponentialRampToValueAtTime(Math.max(120,lp*.25),t+dur);o.connect(f);n=f}n.connect(g);g.connect(out(dest,wet,pan));o.start(t);o.stop(t+dur+.05)}
function hiss(dur,vol,{at=0,t=ctx.currentTime+at,type='lowpass',f0=8000,f1=200,q=.8,wet=0,pan=0,attack=.003,dest}={}){const s=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain();s.buffer=noiseBuf;s.loop=true;f.type=type;f.Q.value=q;f.frequency.setValueAtTime(f0,t);f.frequency.exponentialRampToValueAtTime(Math.max(30,f1),t+dur);env(g,t,vol,attack,dur);s.connect(f);f.connect(g);g.connect(out(dest,wet,pan));s.start(t,Math.random()*1.5);s.stop(t+dur+.05)}
function chord(notes,at,dur,vol,wet=.5){for(const f of notes){osc('sawtooth',f,f,dur,vol,{at,wet,attack:.03,lp:3200});osc('sawtooth',f,f,dur,vol*.7,{at,wet,attack:.03,detune:9,lp:3200})}}
// 배경음악: 132BPM 16분음표 스케줄러. level 0=전투, 1=증원 웨이브, 2=기함전
const BASS=[55,43.65,65.41,49],PAD=[[220,261.6,329.6],[174.6,220,261.6],[261.6,329.6,392],[196,246.9,293.7]],ARP=[440,523.3,659.3,880,659.3,523.3,440,329.6];
function schedule(){const s16=60/132/4;while(next<ctx.currentTime+.15){const t=next,bar=Math.floor(step/16)%4,i=step%16,d=bgmBus;
if(i%4===0){osc('sine',150,42,.32,.9,{t,dest:d});hiss(.03,.25,{t,type:'highpass',f0:3000,f1:2000,dest:d})}
if(i%2===0)osc('sawtooth',BASS[bar]*(i%8===6?2:1),BASS[bar]*(i%8===6?2:1),s16*1.8,.32,{t,lp:900,dest:d});
if(i%4===2)hiss(.05,level?.22:.12,{t,type:'highpass',f0:9000,f1:6000,dest:d});
if(level>=1&&(i===4||i===12)){hiss(.22,.45,{t,type:'bandpass',f0:1800,f1:700,q:.7,dest:d});osc('triangle',220,140,.12,.25,{t,dest:d})}
if(i===0)for(const f of PAD[bar])osc('sawtooth',f,f,s16*16,.05,{t,attack:.4,lp:1400,detune:rnd(-8,8),dest:d});
if(level>=2&&i%2===0)osc('square',ARP[(step/2)%8]*(bar===2?1.5:1),ARP[(step/2)%8]*(bar===2?1.5:1),s16*1.5,.06,{t,lp:2600,dest:d});
step++;next+=s16}}
const api={init,refresh:applyVolume,
volume(v){volume=T.MathUtils.clamp(v,0,1);if(volume>0)muted=false;applyVolume()},
step(d){api.volume(Math.round((volume+d)*20)/20);notify('볼륨 '+Math.round(volume*100)+'%',.8)},
state:()=>({ctx:ctx?.state??'none',bgm:playing,level,volume,muted}),
toggleMute(){init();muted=!muted;applyVolume();if(!muted)api.ui()},
pause(on){if(!ctx)return;on?ctx.suspend():ctx.resume()},
bgm(on,lvl=0){if(!ctx)return;level=lvl;if(on&&!playing){playing=true;step=0;next=ctx.currentTime+.1;clearInterval(timer);timer=setInterval(schedule,25);bgmBus.gain.setTargetAtTime(.55,ctx.currentTime,.4)}if(!on&&playing){playing=false;bgmBus.gain.setTargetAtTime(0,ctx.currentTime,.25);setTimeout(()=>{if(!playing)clearInterval(timer)},1200)}},
intensity(l){level=l},
boost(on){if(!ctx)return;const t=ctx.currentTime;boostGain.gain.setTargetAtTime(on?.32:0,t,on?.08:.25);boostFilter.frequency.setTargetAtTime(on?1600:400,t,.3)},
ui(){if(live())osc('sine',880,1320,.12,.12,{wet:.2})},
launch(){if(!live())return;hiss(1.8,.5,{type:'bandpass',f0:180,f1:3000,q:.7,attack:.7,wet:.4});osc('sawtooth',45,120,1.6,.3,{attack:.6,lp:1800});chord([261.6,329.6,392],.55,.35,.07);chord([349.2,440,523.3],.9,.35,.07);chord([392,493.9,587.3,784],1.25,1.4,.07)},
laser(){if(!live()||!gate('laser',45))return;const r=rnd(.97,1.05);osc('sawtooth',1900*r,320,.11,.09,{wet:.12,pan:-.35});osc('sawtooth',1950*r,300,.11,.09,{wet:.12,pan:.35,detune:12});osc('square',3800*r,900,.05,.03)},
plasma(){if(!live())return;osc('square',330,55,.32,.16,{wet:.25});osc('sawtooth',165,40,.38,.13,{detune:-15});hiss(.3,.24,{type:'bandpass',f0:2600,f1:300,q:1.2,wet:.3})},
missile(){if(!live())return;hiss(.9,.3,{type:'bandpass',f0:500,f1:4200,q:2,wet:.3,attack:.05});osc('sawtooth',90,45,.7,.16,{attack:.04,lp:1200})},
rail(){if(!live())return;hiss(.25,.6,{type:'highpass',f0:9000,f1:1500,wet:.4});osc('sine',120,30,.6,.7,{wet:.5});osc('sawtooth',2600,180,.35,.14,{wet:.5});osc('sine',2400,1800,.9,.07,{at:.05,wet:.7})},
emp(){if(!live())return;osc('sine',150,26,1.9,.9,{wet:.6});osc('sawtooth',60,25,1.6,.3,{wet:.5,lp:600});osc('sine',400,3200,.6,.14,{attack:.3,wet:.6});hiss(2.4,.7,{f0:7000,f1:70,wet:.8,attack:.02});for(let i=0;i<8;i++)osc('sine',rnd(1800,4200),rnd(1500,3000),.4,.05,{at:rnd(.1,1.2),wet:.9,pan:rnd(-.9,.9)})},
hit(pan=0){if(!live()||!gate('hit',30))return;osc('triangle',rnd(1200,1500),600,.07,.08,{pan});hiss(.05,.1,{type:'highpass',f0:5000,f1:3000,pan})},
explode(pan=0,big=false){if(!live()||!gate(big?'boom':'pop',big?60:25))return;if(!big){hiss(.7,.6,{f0:3000,f1:90,wet:.35,pan});osc('sine',120,35,.45,.75,{pan});return}hiss(2.2,1,{f0:5000,f1:50,wet:.7,pan});osc('sine',90,22,1.4,1,{wet:.4,pan});osc('sawtooth',55,25,1.2,.3,{lp:500});for(let i=0;i<6;i++)hiss(.12,.3,{type:'bandpass',f0:rnd(2000,5000),f1:800,q:3,at:rnd(.1,1),pan:pan+rnd(-.4,.4),wet:.4})},
bossDown(){if(!live())return;for(let i=0;i<7;i++){const at=i*.22+rnd(0,.1);hiss(1.8,.9,{f0:4500,f1:45,at,wet:.8,pan:rnd(-.8,.8)});osc('sine',rnd(70,110),22,1.3,.9,{at,wet:.5})}osc('sine',60,18,4,.8,{at:.2,wet:.9,attack:.3})},
hurt(low){if(!live()||!gate('hurt',80))return;osc('square',140,40,.3,.35,{lp:1800});hiss(.35,.7,{f0:1800,f1:100});osc('sawtooth',70,35,.4,.35,{detune:30,lp:900});if(low)for(let i=0;i<2;i++)osc('square',880,880,.08,.1,{at:.15+i*.16})},
enemyShot(pan=0){if(live()&&gate('eshot',90))osc('sawtooth',700,180,.12,.04,{pan,wet:.2,lp:2400})},
bossShot(){if(!live())return;osc('sawtooth',260,70,.45,.18,{wet:.4,lp:1400});hiss(.3,.25,{type:'bandpass',f0:900,f1:300,q:1.5,wet:.3})},
weapon(i){if(!live())return;const f=[523.3,587.3,659.3,784,880][i];osc('triangle',f,f,.09,.12);osc('sine',f*2,f*2,.14,.08,{at:.05,wet:.3})},
wave(){if(!live())return;[392,523.3,659.3,784,1046.5].forEach((f,i)=>osc('sawtooth',f,f,.3,.09,{at:i*.09,wet:.5,lp:3000}));hiss(1.1,.35,{type:'bandpass',f0:300,f1:5000,q:1,attack:.4,wet:.5})},
alarm(){if(!live())return;for(let i=0;i<4;i++){osc('sawtooth',660,660,.28,.13,{at:i*.6,wet:.3,lp:2500});osc('sawtooth',440,440,.28,.13,{at:i*.6+.3,wet:.3,lp:2500})}osc('sawtooth',55,52,2.6,.4,{attack:.5,wet:.6,lp:700});osc('sawtooth',82.4,80,2.6,.3,{attack:.5,wet:.6,lp:700})},
victory(){if(!live())return;chord([523.3,659.3,784],0,.32,.08);chord([587.3,740,880],.35,.32,.08);chord([659.3,830.6,987.8,1318.5],.7,2.2,.08);osc('sine',65.4,65.4,2.6,.4,{at:.7,attack:.05,wet:.5})},
defeat(){if(!live())return;[392,311.1,261.6,196].forEach((f,i)=>chord([f,f*1.19],i*.45,.6,.07,.6));hiss(3,.5,{f0:900,f1:40,wet:.8,attack:.2});osc('sine',55,25,3,.6,{wet:.6})}};
return api})();
function notify(text,d=2){$('#notice').textContent=text;noticeUntil=time+d;$('#notice').style.opacity=1}
function remove(m){m.parent?.remove(m);m.traverse(o=>{if(o.isSprite||o.userData.disposableMaterial)o.material.dispose();if(o.userData.disposable){o.geometry?.dispose();o.material?.dispose()}})}
function reset(){for(const o of [...enemies,...shots,...enemyShots,...effects])remove(o.mesh);enemies=[];shots=[];enemyShots=[];effects=[];particles=[];boss=null;elapsed=0;wave=1;waveKills=0;score=0;kills=0;shield=100;energy=100;missiles=12;fireTimer=0;missileTimer=0;empTimer=0;spawnTimer=.2;hitTime=0;victoryTimer=0;$('#damage').style.opacity=0;$('#hit-marker').style.opacity=0;player.position.set(0,-1,6);for(const k in keys)delete keys[k];mouse.down=false;joy.x=joy.y=0;mouse.x=mouse.y=0;paused=false;wasBoosting=false;sfx.boost(false);sfx.pause(false);setWeapon(0)}
function start(){reset();mode='play';document.body.classList.add('playing');for(const id of ['hud','reticle','bottom-hud','weapon-bar'])$('#'+id).hidden=false;$('#touch').hidden=!mobile;$('#modal').hidden=true;$('#paused').hidden=true;$('#boss-hud').hidden=true;$('#pause').textContent='Ⅱ';notify('전 기체 출격 · '+planets[selected][0]+' 궤도 방어',3);sfx.init();sfx.launch();sfx.bgm(true,0);for(let i=0;i<18;i++)spawnEnemy(true)}
function finish(win){if(mode!=='play')return;mode='end';mouse.down=false;best=Math.max(best,Math.floor(score));try{localStorage.setItem('solarWarBest',best)}catch{}$('#end-label').textContent=win?'VICTORY / SECTOR SECURED':'DEFEAT / SIGNAL LOST';$('#end-title').textContent=win?'적 기함 격침. 궤도 확보.':'다시, 전장으로.';$('#end-desc').textContent=win?planets[selected][0]+' 방어 성공. 외계 함대가 퇴각합니다.':'방어막이 소진되었습니다. 무기를 바꾸고 부스트로 적의 포화를 피하세요.';$('#end-score').textContent=Math.floor(score).toLocaleString();$('#end-kills').textContent=kills;$('#best').textContent='BEST '+String(best).padStart(6,'0');$('#modal').hidden=false;$('#touch').hidden=true;$('#reticle').hidden=true;$('#boss-hud').hidden=true;sfx.bgm(false);sfx.boost(false);win?sfx.victory():sfx.defeat()}
function togglePause(){if(mode!=='play')return;paused=!paused;sfx.pause(paused);$('#paused').hidden=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';mouse.down=false;for(const k in keys)delete keys[k];joy.x=joy.y=0}
function hangar(){reset();mode='intro';sfx.bgm(false);sfx.boost(false);document.body.classList.remove('playing');for(const id of ['hud','reticle','bottom-hud','weapon-bar','boss-hud','touch','modal','paused'])$('#'+id).hidden=true;$('#notice').textContent=''}
function spawnEnemy(initial=false){if(enemies.length>=36)return;const type=Math.floor(Math.random()*4),g=fighter(type),x=(Math.random()-.5)*64,y=(Math.random()-.5)*30;g.position.set(x,y,initial?-35-Math.random()*100:-120-Math.random()*40);g.rotation.y=Math.PI;g.scale.setScalar(type===2?1.4:1.05+wave*.07);world.add(g);enemies.push({mesh:g,hp:type===2?6:3,speed:12+Math.random()*10+wave*2,type,seed:Math.random()*20,shoot:1.2+Math.random()*3,baseX:x,baseY:y,dead:false})}
function spawnBoss(){const g=capital();g.rotation.y=Math.PI;g.position.set(0,5,-140);world.add(g);boss={mesh:g,hp:260,maxHp:260,shoot:1,dead:false};enemies.push(boss);$('#boss-hud').hidden=false;notify('WARNING · 외계 기함 출현',4);sfx.alarm();sfx.intensity(2)}
function aimPoint(){let lock=null,d=.11;for(const e of enemies){if(e.dead||e.mesh.position.z>0)continue;const p=e.mesh.position.clone().project(camera),v=Math.hypot(p.x-mouse.x,p.y-mouse.y);if(v<d){d=v;lock=e}}if(lock)return lock.mesh.position.clone().add(new V(0,0,lock===boss?0:1));const p=new V(mouse.x,mouse.y,.5).unproject(camera),dir=p.sub(camera.position).normalize();return camera.position.clone().add(dir.multiplyScalar((-95-camera.position.z)/dir.z))}
function projectile(pos,dir,color,damage=1,spd=200,kind='laser',hostile=false){const g=new T.Group(),rail=kind==='rail',missile=kind==='missile';if(missile){mesh(geometries.missile??=new T.ConeGeometry(.18,1.5,8),mat(0xdce0cf),g).rotation.x=-Math.PI/2;glow(0xff9b44,1.7,g,0,0,.8)}else{const m=mesh(geometries[rail?'rail':'bolt']??=new T.CylinderGeometry(rail?.12:.065,rail?.12:.065,rail?12:2.8,5),new T.MeshBasicMaterial({color}),g);m.userData.disposableMaterial=true;m.rotation.x=Math.PI/2;glow(color,rail?2:1.2,g)}g.position.copy(pos);g.quaternion.setFromUnitVectors(new V(0,0,-1),dir);world.add(g);const o={mesh:g,dir:dir.clone(),speed:spd,life:missile?5:2.8,damage,kind,trail:0,hit:new Set()};(hostile?enemyShots:shots).push(o);return o}
function nearestTarget(){let nearest=null,d=Infinity;const aim=aimPoint();for(const e of enemies){if(e.dead)continue;const p=e.mesh.position,metric=Math.hypot(p.x-aim.x,p.y-aim.y)+Math.abs(p.z+60)*.08;if(metric<d){d=metric;nearest=e}}return nearest}
function fireMissile(){if(missileTimer>0||missiles<1)return false;missiles--;missileTimer=.5;const pos=player.position.clone().add(new V(0,-.5,-2)),e=nearestTarget(),dir=e?e.mesh.position.clone().sub(pos).normalize():aimPoint().sub(pos).normalize();projectile(pos,dir,0xffb35b,18,66,'missile').target=e;sfx.missile();return true}
function fire(){if(fireTimer>0)return;const w=weapons[weapon];if(weapon===2){if(fireMissile())fireTimer=w.cool;else{fireTimer=.25;if(missiles<1)notify('미사일 소진 · 다른 무기를 사용하세요',1)}return}if(weapon===4){if(empTimer>0){fireTimer=.3;return}empTimer=9;fireTimer=.6;shockwave(player.position.clone().add(new V(0,0,-25)),0x91aaff,85);for(const e of [...enemies]){if(!e.dead){e.shoot+=3;damageEnemy(e,e===boss?30:12)}}for(const s of enemyShots)remove(s.mesh);enemyShots=[];shake=.65;sfx.emp();notify('EMP NOVA · 적 탄막 소거',1.5);return}fireTimer=w.cool;const aim=aimPoint(),orig=player.position.clone();if(weapon===0){for(const side of [-1,1]){const pos=orig.clone().add(new V(side*1.95,0,-1.5));projectile(pos,aim.clone().sub(pos).normalize(),w.color,1,250)}sfx.laser()}if(weapon===1){for(let i=-2;i<=2;i++){const p=orig.clone().add(new V(i*.2,0,-2)),dir=aim.clone().sub(p).normalize();dir.x+=i*.055;dir.y+=Math.abs(i)*.006;projectile(p,dir.normalize(),w.color,2,170,'plasma')}sfx.plasma()}if(weapon===3){const pos=orig.clone().add(new V(0,0,-2));projectile(pos,aim.clone().sub(pos).normalize(),w.color,10,490,'rail');shake=.14;sfx.rail()}}
function explosion(pos,color=0xffa45d,big=false){const col=new T.Color(color);for(let i=0;i<(big?170:42)&&particles.length<2100;i++)particles.push({pos:pos.clone(),vel:new V(Math.random()-.5,Math.random()-.5,Math.random()-.5).normalize().multiplyScalar((big?30:12)*(Math.random()+.2)),color:col.clone().lerp(new T.Color(0xfff3c2),Math.random()*.6),life:big?1.8:.8,max:big?1.8:.8});const s=glow(color,big?42:10,world,pos.x,pos.y,pos.z);effects.push({mesh:s,life:big?1:.3,max:big?1:.3,kind:'flash',size:big?42:10});if(big)shockwave(pos,color,45)}
function shockwave(pos,color,size){const m=new T.Mesh(new T.RingGeometry(.8,1,80),new T.MeshBasicMaterial({color,transparent:true,side:T.DoubleSide,blending:T.AdditiveBlending,depthWrite:false}));m.position.copy(pos);world.add(m);m.userData.disposable=true;effects.push({mesh:m,life:.9,max:.9,kind:'ring',size})}
function damageEnemy(e,amount){if(e.dead)return;e.hp-=amount;hitTime=.1;if(e.hp<=0){e.dead=true;const p=e.mesh.position.clone();explosion(p,e===boss?0xffac69:0xff8847,e===boss||e.type===2);remove(e.mesh);kills++;waveKills++;score+=e===boss?12000:e.type===2?350:200;shield=Math.min(100,shield+1.6);if(kills%7===0)missiles=Math.min(24,missiles+2);sfx.explode(panOf(p),e===boss||e.type===2);if(e===boss){for(let i=0;i<9;i++)explosion(p.clone().add(new V((Math.random()-.5)*18,(Math.random()-.5)*8,(Math.random()-.5)*22)),0xffb46e,true);shake=1.3;victoryTimer=1.8;sfx.bossDown();notify('기함 격침 · SECTOR SECURED',3)}}else{explosion(e.mesh.position,0x88eaff);sfx.hit(panOf(e.mesh.position))}}
function takeDamage(amount){if(mode!=='play'||victoryTimer>0)return;shield-=amount;shake=Math.max(shake,.35);$('#damage').style.opacity=.7;sfx.hurt(shield<30);if(shield<=0){shield=0;explosion(player.position,0xff9955,true);finish(false)}}
function panOf(p){return T.MathUtils.clamp((p.x-player.position.x)/25,-.9,.9)}
function segmentDistance(p,a,b){const ab=b.clone().sub(a),den=ab.lengthSq();if(!den)return p.distanceTo(a);const t=T.MathUtils.clamp(p.clone().sub(a).dot(ab)/den,0,1);return p.distanceTo(a.clone().addScaledVector(ab,t))}
function update(dt){time+=dt;if(mode!=='play'){if(mode==='intro'){player.position.set(3,-3.7,4);player.rotation.set(-.1,Math.sin(time*.15)*.17,-.18);player.scale.setScalar(1.5);camera.position.lerp(new V(-1,4,20),.03);camera.lookAt(0,0,-45)}return}elapsed+=dt;if(victoryTimer>0){victoryTimer-=dt;if(victoryTimer<=0){finish(true);return}}player.scale.setScalar(1);fireTimer-=dt;missileTimer-=dt;empTimer=Math.max(0,empTimer-dt);hitTime=Math.max(0,hitTime-dt);shake=Math.max(0,shake-dt*1.8);shield=Math.min(100,shield+dt*.35);const boosting=(keys.ShiftLeft||keys.ShiftRight||keys.boost)&&energy>1;energy=T.MathUtils.clamp(energy+(boosting?-30:15)*dt,0,100);if(boosting!==wasBoosting){wasBoosting=boosting;sfx.boost(boosting)}const mx=((keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0))+joy.x,my=((keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0))-joy.y,speed=boosting?31:16;player.position.x=T.MathUtils.clamp(player.position.x+mx*speed*dt,-24,24);player.position.y=T.MathUtils.clamp(player.position.y+my*speed*dt,-12,15);player.rotation.z=T.MathUtils.lerp(player.rotation.z,-mx*.42,dt*9);player.rotation.x=T.MathUtils.lerp(player.rotation.x,my*.18,dt*9);player.rotation.y=T.MathUtils.lerp(player.rotation.y,-mx*.1,dt*9);for(const e of player.userData.engines)e.scale.setScalar((boosting?2.9:1.5)*(1+Math.random()*.18));camera.fov=T.MathUtils.lerp(camera.fov,boosting?76:62,dt*3);camera.updateProjectionMatrix();camera.position.lerp(new V(player.position.x*.24,4+player.position.y*.18,boosting?19:18),dt*4);camera.position.x+=(Math.random()-.5)*shake*.8;camera.position.y+=(Math.random()-.5)*shake*.7;camera.lookAt(player.position.x*.18,player.position.y*.12,-65);
if(mouse.down||keys.Space||keys.fire)fire();if(keys.KeyQ||keys.missile)fireMissile();spawnTimer-=dt;const maxEnemies=wave===3?34:22+wave*3;if(spawnTimer<=0&&enemies.filter(e=>!e.dead).length<maxEnemies){spawnEnemy();spawnTimer=wave===3?.4:.6}if(wave===1&&waveKills>=12){wave=2;waveKills=0;missiles+=5;shield=Math.min(100,shield+20);notify('WAVE 02 · 외계 증원 함대 접근',3);sfx.wave();sfx.intensity(1);for(let i=0;i<7;i++)spawnEnemy()}if(wave===2&&waveKills>=18){wave=3;waveKills=0;missiles+=8;shield=Math.min(100,shield+25);spawnBoss()}
for(const e of enemies){if(e.dead)continue;if(e===boss){e.mesh.position.z=T.MathUtils.lerp(e.mesh.position.z,-80,dt*.3);e.mesh.position.x=Math.sin(time*.22)*17;e.mesh.position.y=7+Math.sin(time*.35)*4;e.shoot-=dt;if(e.shoot<=0){e.shoot=.65;for(let i=-2;i<=2;i++){const pos=e.mesh.position.clone().add(new V(i*2.8,-.5,10)),dir=player.position.clone().sub(pos).normalize();dir.x+=i*.025;projectile(pos,dir.normalize(),0xff5463,8,55,'enemy',true)}sfx.bossShot()}continue}e.mesh.position.z+=e.speed*dt;e.mesh.position.x=e.baseX+Math.sin(time*1.1+e.seed)*5;e.mesh.position.y=e.baseY+Math.cos(time*.8+e.seed)*3;e.mesh.rotation.z=Math.sin(time+e.seed)*.4;e.shoot-=dt;if(e.shoot<0&&e.mesh.position.z<-8){e.shoot=2.2+Math.random()*2;const p=e.mesh.position.clone(),dir=player.position.clone().add(new V((Math.random()-.5)*5,(Math.random()-.5)*4,0)).sub(p).normalize();projectile(p,dir,e.type===2?0x92ff66:0xff4d67,7+wave,48+wave*3,'enemy',true);sfx.enemyShot(panOf(p))}if(e.mesh.position.distanceTo(player.position)<2.8){takeDamage(18);explosion(e.mesh.position);sfx.explode(panOf(e.mesh.position));e.mesh.position.z=-130}if(e.mesh.position.z>22){e.mesh.position.z=-130;e.baseX=(Math.random()-.5)*60;e.baseY=(Math.random()-.5)*27}}
for(const s of shots){const prev=s.mesh.position.clone();if(s.kind==='missile'&&s.target&&!s.target.dead){s.dir.lerp(s.target.mesh.position.clone().sub(s.mesh.position).normalize(),Math.min(1,dt*5)).normalize();s.mesh.quaternion.setFromUnitVectors(new V(0,0,-1),s.dir);s.trail-=dt;if(s.trail<0&&particles.length<2100){s.trail=.035;particles.push({pos:s.mesh.position.clone(),vel:new V(0,0,3),color:new T.Color(0xffa158),life:.35,max:.35})}}s.mesh.position.addScaledVector(s.dir,s.speed*dt);s.life-=dt;for(const e of enemies){if(e.dead||s.hit.has(e))continue;if(segmentDistance(e.mesh.position,prev,s.mesh.position)<(e===boss?8.5:e.type===2?2.4:2)){s.hit.add(e);damageEnemy(e,s.damage);if(s.kind==='missile'){explosion(s.mesh.position,0xffae60,true);sfx.explode(panOf(s.mesh.position),true);for(const other of enemies)if(other!==e&&!other.dead&&other.mesh.position.distanceTo(s.mesh.position)<12)damageEnemy(other,8)}if(s.kind!=='rail'){s.life=-1;break}}}}for(const s of enemyShots){const prev=s.mesh.position.clone();s.mesh.position.addScaledVector(s.dir,s.speed*dt);s.life-=dt;if(segmentDistance(player.position,prev,s.mesh.position)<(boosting?.65:1.25)){s.life=-1;takeDamage(s.damage)}}for(const arr of [shots,enemyShots])for(let i=arr.length-1;i>=0;i--)if(arr[i].life<=0){arr[i].mesh.traverse(o=>{if(o.userData.disposableMaterial)o.material.dispose()});remove(arr[i].mesh);arr.splice(i,1)}enemies=enemies.filter(e=>!e.dead);if(time>noticeUntil)$('#notice').style.opacity=0;updateHUD(boosting)}
function updateHUD(boosting){$('#score').textContent=String(Math.floor(score)).padStart(6,'0');$('#kills').textContent=String(kills).padStart(2,'0');$('#missiles').textContent=String(missiles).padStart(2,'0');$('#shield-value').textContent=Math.ceil(shield)+'%';$('#shield').style.width=shield+'%';$('#shield').style.background=shield<30?'#ff6657':'#81f4ff';$('#energy').style.width=energy+'%';$('#boost-value').textContent=boosting?'BOOSTING':energy>99?'READY':Math.floor(energy)+'%';$('#wave').textContent='0'+wave;$('#objective').textContent=wave===3?'적 기함 격침':`적 전투기 격추 ${waveKills} / ${wave===1?12:18}`;if(boss&&!boss.dead)$('#boss-health').style.width=Math.max(0,boss.hp/boss.maxHp*100)+'%';if(frame%8===0){$('#radar-blips').innerHTML=enemies.slice(0,36).map(e=>`<i style="left:${50+T.MathUtils.clamp((e.mesh.position.x-player.position.x)*1.1,-43,43)}%;top:${75+T.MathUtils.clamp((e.mesh.position.z-6)*.43,-65,10)}%"></i>`).join('');document.querySelectorAll('#weapon-bar button').forEach((b,i)=>b.querySelector('i').textContent=i===2?'×'+missiles:i===4?(empTimer>0?Math.ceil(empTimer)+'s':'READY'):'')}const rx=(mouse.x+1)*W/2,ry=(1-mouse.y)*H/2;$('#reticle').style.left=rx+'px';$('#reticle').style.top=ry+'px';$('#hit-marker').style.left=rx+'px';$('#hit-marker').style.top=ry+'px';$('#hit-marker').style.opacity=hitTime>0?1:0;$('#damage').style.opacity=Math.max(0,parseFloat($('#damage').style.opacity||0)-.035)}
function animateWorld(dt){planetGroup.userData.body.rotation.y+=dt*.012;stars.rotation.y+=dt*.001;for(const a of allies){a.mesh.position.z-=dt*a.speed;a.mesh.position.x+=Math.sin(time*.3+a.seed)*dt*2;a.mesh.rotation.z=Math.sin(time*.4+a.seed)*.2;if(a.mesh.position.z<-180){a.mesh.position.z=15;a.mesh.position.x=(Math.random()-.5)*95;a.mesh.position.y=(Math.random()-.5)*35}if(Math.random()<dt*.8){const m=new T.Mesh(geometries.ambient??=new T.CylinderGeometry(.08,.08,6,4),new T.MeshBasicMaterial({color:a.friendly?0x5de2ff:0xff425b}));m.rotation.x=Math.PI/2;m.position.copy(a.mesh.position);world.add(m);ambient.push({mesh:m,dir:new V((Math.random()-.5)*.2,(Math.random()-.5)*.15,-1).normalize(),life:1})}}for(let i=ambient.length-1;i>=0;i--){const a=ambient[i];a.mesh.position.addScaledVector(a.dir,170*dt);a.life-=dt;if(a.life<=0){a.mesh.material.dispose();remove(a.mesh);ambient.splice(i,1)}}if(Math.random()<dt*.4&&mode==='intro')explosion(new V((Math.random()-.5)*100,(Math.random()-.5)*25,-50-Math.random()*90),0xff8f69,true);for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.life<=0){particles.splice(i,1);continue}p.pos.addScaledVector(p.vel,dt);p.vel.multiplyScalar(Math.max(0,1-dt*1.5))}for(let i=0;i<particles.length;i++){const p=particles[i],a=p.life/p.max;particlePositions.set([p.pos.x,p.pos.y,p.pos.z],i*3);particleColors.set([p.color.r*a,p.color.g*a,p.color.b*a],i*3)}particleGeo.setDrawRange(0,particles.length);particleGeo.attributes.position.needsUpdate=true;particleGeo.attributes.color.needsUpdate=true;for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;const progress=1-e.life/e.max;e.mesh.material.opacity=Math.max(0,1-progress);e.mesh.scale.setScalar(e.kind==='ring'?1+progress*e.size:e.size*(1+progress*.5));if(e.life<=0){remove(e.mesh);effects.splice(i,1)}}}
function loop(now){const dt=Math.min((now-last)/1000,.035);last=now;frame++;if(!paused){update(dt);animateWorld(dt)}renderer.render(scene,camera);requestAnimationFrame(loop)}
addEventListener('resize',()=>{W=innerWidth;H=innerHeight;renderer?.setSize(W,H);if(camera){camera.aspect=W/H;camera.updateProjectionMatrix()}});
$('#start').onclick=start;$('#restart').onclick=start;$('#hangar').onclick=hangar;$('#pause').onclick=togglePause;$('#resume').onclick=togglePause;$('#sound').onclick=()=>sfx.toggleMute();$('#volume').oninput=e=>{sfx.init();sfx.volume(e.target.value/100)};$('#volume').onchange=e=>{e.target.blur();sfx.ui()};sfx.refresh();
addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='KeyP'&&!e.repeat)togglePause();if(e.code==='Enter'&&mode==='intro')start();if(e.code==='Minus'||e.code==='NumpadSubtract')sfx.step(-.1);if(e.code==='Equal'||e.code==='NumpadAdd')sfx.step(.1);if(e.code==='KeyM'&&!e.repeat)sfx.toggleMute();if(e.code.startsWith('Digit')&&Number(e.key)>=1&&Number(e.key)<=5)setWeapon(Number(e.key)-1)});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('blur',()=>{if(mode==='play'&&!paused)togglePause();mouse.down=false;for(const k in keys)delete keys[k]});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='play'&&!paused)togglePause()});
addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;mouse.x=e.clientX/W*2-1;mouse.y=1-e.clientY/H*2});$('#universe').addEventListener('pointerdown',e=>{if(mode==='play'&&!paused){mouse.down=true;mouse.x=e.clientX/W*2-1;mouse.y=1-e.clientY/H*2}});addEventListener('pointerup',()=>mouse.down=false);addEventListener('contextmenu',e=>e.preventDefault());
for(const [id,k] of [['touch-fire','fire'],['touch-boost','boost'],['touch-missile','missile']]){const b=$('#'+id);b.onpointerdown=e=>{e.preventDefault();e.stopPropagation();b.setPointerCapture(e.pointerId);keys[k]=true;if(k==='fire'){mouse.x=0;mouse.y=0}};b.onpointerup=b.onpointercancel=()=>keys[k]=false}const stick=$('#joystick');let stickPointer=null;function stickMove(e){if(stickPointer!==e.pointerId)return;const r=stick.getBoundingClientRect();joy.x=T.MathUtils.clamp((e.clientX-r.left-r.width/2)/40,-1,1);joy.y=T.MathUtils.clamp((e.clientY-r.top-r.height/2)/40,-1,1);stick.firstElementChild.style.transform=`translate(${joy.x*30}px,${joy.y*30}px)`;mouse.x=joy.x*.65;mouse.y=-joy.y*.5}stick.onpointerdown=e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e)};stick.onpointermove=stickMove;stick.onpointerup=stick.onpointercancel=()=>{stickPointer=null;joy.x=joy.y=0;stick.firstElementChild.style.transform='';mouse.x=mouse.y=0};
try{init();new T.TextureLoader().load('./assets/earth.jpg',tex=>{tex.colorSpace=T.SRGBColorSpace;const old=textures.get(2);textures.set(2,tex);if(selected===2){planetGroup.userData.body.material.map=tex;planetGroup.userData.body.material.needsUpdate=true}old?.dispose()})}catch(e){console.error(e);$('#loading').innerHTML='3D 전장을 시작할 수 없습니다.<span>WebGL 지원 브라우저에서 하드웨어 가속을 켜고 다시 열어주세요.</span>'}
window.solarWar={getState:()=>({mode,paused,wave,kills,score,shield,energy,missiles,weapon:weapons[weapon].name,enemies:enemies.length,shots:shots.length,enemyShots:enemyShots.length,bossHP:boss?.hp,drawCalls:renderer?.info.render.calls,triangles:renderer?.info.render.triangles,webgl:!!renderer,selectedPlanet:planets[selected][1],audio:sfx.state()})};
